const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let statusData={},configData={},activeModule='Home',activeView='dashboard';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(url,opt={}){const r=await fetch(url,opt);let d={};try{d=await r.json()}catch{d={detail:await r.text()}}if(!r.ok)throw new Error(d.detail||`HTTP ${r.status}`);return d}
const jpost=(url,data)=>api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.remove('hidden');clearTimeout(toast._t);toast._t=setTimeout(()=>t.classList.add('hidden'),3200)}

const SS_MODAL_SIZE_PREFIX='surveysync-modal-size:';
function applyModalSize(key='default',large=false){const modal=$('#modal'),dialog=modal?.querySelector('.dialog');if(!modal||!dialog)return;modal.dataset.modalKey=key;modal.classList.toggle('crs-open',!!large);dialog.style.width='';dialog.style.height='';try{const saved=JSON.parse(localStorage.getItem(SS_MODAL_SIZE_PREFIX+key)||'{}');if(saved.width)dialog.style.width=Math.min(saved.width,window.innerWidth*.96)+'px';if(saved.height)dialog.style.height=Math.min(saved.height,window.innerHeight*.94)+'px'}catch{}}
function rememberModalSize(){const modal=$('#modal'),dialog=modal?.querySelector('.dialog');if(!modal||!dialog||modal.classList.contains('hidden'))return;const key=modal.dataset.modalKey||'default';const r=dialog.getBoundingClientRect();if(r.width>200&&r.height>150)localStorage.setItem(SS_MODAL_SIZE_PREFIX+key,JSON.stringify({width:Math.round(r.width),height:Math.round(r.height)}))}
function openModalShell(key='default',large=false){applyModalSize(key,large);$('#modal').classList.remove('hidden')}
function closeModalShell(){rememberModalSize();const modal=$('#modal');modal.classList.add('hidden');modal.classList.remove('crs-open');modal.dataset.modalKey='default'}
window.addEventListener('beforeunload',rememberModalSize);

const SS_RELEASE_SEEN_KEY='surveysync-release-notes-seen';
let releaseNotesData={version:'',notes:[]};
async function loadReleaseNotes(showOnUpgrade=true){
  try{
    const d=await api('/api/v9/release-notes');releaseNotesData=d||{};
    const version=String(d.version||'').trim();const notes=Array.isArray(d.notes)?d.notes:[];
    if($('#whatsNewTitle'))$('#whatsNewTitle').textContent=`What's new in SurveySync ${version?`v${version}`:''}`;
    if($('#whatsNewVersion'))$('#whatsNewVersion').textContent=version?`v${version}`:'Latest';
    if($('#whatsNewList'))$('#whatsNewList').innerHTML=notes.map(x=>`<li>${esc(x)}</li>`).join('')||'<li>No release notes available.</li>';
    if(showOnUpgrade&&version&&localStorage.getItem(SS_RELEASE_SEEN_KEY)!==version){openReleaseNotes(true)}
  }catch(e){if($('#whatsNewList'))$('#whatsNewList').innerHTML=`<li>${esc(e.message)}</li>`}
}
function openReleaseNotes(markSeen=false){
  const d=releaseNotesData||{},version=String(d.version||'').trim(),notes=Array.isArray(d.notes)?d.notes:[];
  openModalShell('release-notes');$('#modalBody').innerHTML=`<div class="release-dialog"><img src="/surveysync-static/surveysync_logo.jpg" alt="SurveySync — Unifying Global Data" style="display:block;width:180px;margin:0 auto 16px"><div class="eyebrow">WHAT'S NEW</div><h2>SurveySync ${version?`v${esc(version)}`:''}</h2><p class="muted">Latest application-wide update.</p><ul class="release-list">${notes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="row"><button id="releaseDone" class="primary">Continue</button></div></div>`;
  if(markSeen&&version)localStorage.setItem(SS_RELEASE_SEEN_KEY,version);
  $('#releaseDone').onclick=closeModalShell;
}
function openGlobalFeedbackWizard(prefill=''){
  const q=new URLSearchParams();q.set('feedback','1');if(prefill)q.set('feedback_type',prefill);location.href=`/fieldbook?${q.toString()}`;
}


// Global application theme ----------------------------------------------------
// These keys are shared with FieldBookSync because both modules run on the
// same local origin. Legacy fbs-* keys are mirrored for backwards compatibility.
const SS_APPEARANCE_KEY='surveysync-appearance';
const SS_PRODUCT_THEME_KEY='surveysync-product-theme';
const SS_ACCENT_KEY='surveysync-accent';
let sharedUiSyncTimer=null;
function currentSharedUiPrefs(){return {appearance:document.documentElement.dataset.themeMode||'system',theme:document.documentElement.dataset.productTheme||'classic',accent:document.documentElement.dataset.accent||'default'}}
function rememberSharedUiPrefs(p){if(!p)return;localStorage.setItem(SS_APPEARANCE_KEY,p.appearance||'system');localStorage.setItem(SS_PRODUCT_THEME_KEY,p.theme||'classic');localStorage.setItem(SS_ACCENT_KEY,p.accent||'default');localStorage.setItem('fbs-theme',p.appearance||'system');localStorage.setItem('fbs-product-theme',p.theme||'classic');localStorage.setItem('fbs-accent',p.accent||'default')}
function scheduleSharedUiSync(){clearTimeout(sharedUiSyncTimer);sharedUiSyncTimer=setTimeout(async()=>{try{await jpost('/api/v9/config/ui',currentSharedUiPrefs())}catch(e){console.warn('SurveySync UI preference sync failed',e)}},80)}
async function loadSharedUiPrefs(){try{const p=await api('/api/v9/config/ui');rememberSharedUiPrefs(p);applyAppearance(p.appearance||'system',false);applyProductTheme(p.theme||'classic',false);applyAccent(p.accent||'default',false);return p}catch(e){console.warn('SurveySync UI preference load failed',e);return null}}
const THEME_PROFILES={
  classic:'FieldBook Classic',edsi:'EDSI Adaptive',slate:'Slate Professional',midnight:'Midnight',lightpro:'Light Professional',contrast:'High Contrast',
  carbon:'Carbon',obsidian:'Obsidian Blue',teal:'Slate Teal',violet:'Midnight Violet',graphite:'Graphite',frost:'Frost',arctic:'Arctic Blue',sandstone:'Sandstone',
  edsidark:'EDSI Dark',edsilight:'EDSI Light'
};
const ACCENTS={default:'Theme default',azure:'Azure',teal:'Teal',emerald:'Emerald',violet:'Violet',amber:'Amber',rose:'Rose'};
function resolveAppearance(mode){return mode==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):mode}
function updateThemeColor(){const meta=document.querySelector('meta[name="theme-color"]');if(meta){const v=getComputedStyle(document.documentElement).getPropertyValue('--topbar').trim();if(v)meta.content=v}}
function updateAppearanceControls(){
  const mode=document.documentElement.dataset.themeMode||'system';
  const glyph=mode==='light'?'☀':mode==='dark'?'◒':'◐';
  const label=mode[0].toUpperCase()+mode.slice(1);
  if($('#appearanceGlyph'))$('#appearanceGlyph').textContent=glyph;
  if($('#appearanceText'))$('#appearanceText').textContent=label;
  $$('[data-global-appearance]').forEach(b=>b.classList.toggle('selected',b.dataset.globalAppearance===mode));
  if($('#globalTheme'))$('#globalTheme').value=document.documentElement.dataset.productTheme||'classic';
  if($('#globalAccent'))$('#globalAccent').value=document.documentElement.dataset.accent||'default';
}
function applyAppearance(mode,persist=true){
  if(!['system','light','dark'].includes(mode))mode='system';
  document.documentElement.dataset.themeMode=mode;
  document.documentElement.dataset.theme=resolveAppearance(mode);
  if(persist){localStorage.setItem(SS_APPEARANCE_KEY,mode);localStorage.setItem('fbs-theme',mode);scheduleSharedUiSync()}
  updateAppearanceControls();updateThemeColor();
}
function applyProductTheme(key,persist=true){
  if(!THEME_PROFILES[key])key='classic';
  document.documentElement.dataset.productTheme=key;
  if(persist){localStorage.setItem(SS_PRODUCT_THEME_KEY,key);localStorage.setItem('fbs-product-theme',key);localStorage.setItem('fbs-product-theme-user-set','1');scheduleSharedUiSync()}
  updateAppearanceControls();
}
function applyAccent(key,persist=true){
  if(!ACCENTS[key])key='default';
  document.documentElement.dataset.accent=key;
  if(persist){localStorage.setItem(SS_ACCENT_KEY,key);localStorage.setItem('fbs-accent',key);scheduleSharedUiSync()}
  updateAppearanceControls();
}
function cycleAppearance(){const mode=document.documentElement.dataset.themeMode||'system';applyAppearance(mode==='system'?'light':mode==='light'?'dark':'system')}
function initGlobalThemeControls(){
  const theme=$('#globalTheme');
  if(theme){theme.innerHTML=Object.entries(THEME_PROFILES).map(([k,v])=>`<option value="${esc(k)}">${esc(v)}</option>`).join('');theme.onchange=()=>{applyProductTheme(theme.value);toast(`${THEME_PROFILES[theme.value]} theme applied to all modules`)}}
  const accent=$('#globalAccent');if(accent)accent.onchange=()=>{applyAccent(accent.value);toast(`${ACCENTS[accent.value]} accent applied to all modules`)};
  $$('[data-global-appearance]').forEach(b=>b.onclick=()=>{applyAppearance(b.dataset.globalAppearance);toast(`${b.textContent.trim()} appearance applied to all modules`)});
  if($('#appearanceBtn'))$('#appearanceBtn').onclick=cycleAppearance;
  updateAppearanceControls();
}
matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if((document.documentElement.dataset.themeMode||'system')==='system')applyAppearance('system',false)});
window.addEventListener('storage',e=>{if([SS_APPEARANCE_KEY,SS_PRODUCT_THEME_KEY,SS_ACCENT_KEY].includes(e.key)){
const SS_UPDATE_CHECK_KEY='surveysync-last-update-check';
async function startupUpdateCheck(force=false){
  const last=Number(localStorage.getItem(SS_UPDATE_CHECK_KEY)||0),now=Date.now();
  if(!force&&last&&now-last<12*60*60*1000){if($('#startupUpdateBadge'))$('#startupUpdateBadge').textContent='Automatic check enabled';return}
  try{const d=await api('/api/v9/update/check');localStorage.setItem(SS_UPDATE_CHECK_KEY,String(now));if($('#startupUpdateBadge'))$('#startupUpdateBadge').textContent=d.update_available?`v${d.version} available`:'Up to date';if($('#startupUpdateMsg'))$('#startupUpdateMsg').textContent=d.update_available?`SurveySync ${d.version} is available on the ${d.channel} channel. Click Check & Update when ready.`:`SurveySync ${d.current_version} is current on the ${d.channel} channel.`}catch(e){if($('#startupUpdateBadge'))$('#startupUpdateBadge').textContent='Offline';if($('#startupUpdateMsg'))$('#startupUpdateMsg').textContent=`Update check unavailable: ${e.message}`}
}
if($('#homeFeedback'))$('#homeFeedback').onclick=()=>openGlobalFeedbackWizard();if($('#homeCheckUpdate'))$('#homeCheckUpdate').onclick=()=>{$('#checkUpdate')?.click();switchView('settings')};
setTimeout(()=>startupUpdateCheck(false),900);

applyAppearance(localStorage.getItem(SS_APPEARANCE_KEY)||'system',false);applyProductTheme(localStorage.getItem(SS_PRODUCT_THEME_KEY)||'classic',false);applyAccent(localStorage.getItem(SS_ACCENT_KEY)||'default',false)}});

