function closeMenus(){ $$('.desktop-menu').forEach(m=>m.classList.add('hidden')); $$('.menu-trigger').forEach(b=>b.classList.remove('open')) }
$$('.menu-trigger').forEach(b=>b.onclick=e=>{e.stopPropagation();const menu=$('#'+b.dataset.menu),open=!menu.classList.contains('hidden');closeMenus();if(open)return;const r=b.getBoundingClientRect();menu.style.left=`${r.left}px`;menu.style.top=`${r.bottom+2}px`;menu.classList.remove('hidden');b.classList.add('open')});
document.addEventListener('click',e=>{if(!e.target.closest('.desktop-menu')&&!e.target.closest('.menu-trigger'))closeMenus()});

function renderModuleNav(){const m=modules[activeModule]||modules.Home;$('#moduleKicker').textContent=activeModule==='Home'?'SURVEYSYNC':'MODULE';$('#moduleName').textContent=activeModule;$('#moduleDescription').textContent=m.desc;let last='';$('#moduleNav').innerHTML=m.nav.map(([group,label,view,ico],i)=>{let h='';if(group!==last){h=`<div class="module-nav-label">${esc(group)}</div>`;last=group}return h+`<button class="module-nav-btn ${view===activeView?'active':''}" data-view="${view}" data-nav-index="${i}"><span class="nav-ico">${ico}</span><span>${esc(label)}</span></button>`}).join('');$$('#moduleNav .module-nav-btn').forEach(b=>b.onclick=()=>switchView(b.dataset.view,b.textContent.trim()))}
function setFoundation(label){const f=foundationCopy[activeModule]||[activeModule,'This module is connected to the common SurveySync foundation.',['Shared Project','Shared Points','Shared CRS','Shared Audit']];$('#foundationKicker').textContent=activeModule.toUpperCase();$('#foundationTitle').textContent=label&&label!==activeModule?label:f[0];$('#foundationText').textContent=f[1];$('#foundationIcon').textContent=(activeModule==='Home'?'H':activeModule[0]);$('#foundationCards').innerHTML=f[2].map(x=>`<div class="foundation-card"><h3>${esc(x)}</h3><p>Uses the same project identity, CRS/units, provenance and audit conventions as the rest of SurveySync.</p><span class="status">FOUNDATION READY</span></div>`).join('')}
function switchView(v,label=''){activeView=v;$$('.view').forEach(x=>x.classList.toggle('active',x.id===v));const meta=viewMeta[v]||viewMeta.foundation;$('#viewTitle').textContent=label||meta[0];$('#viewSub').textContent=meta[1];$('#workspaceModule').textContent=activeModule.toUpperCase();renderModuleNav();if(v==='foundation')setFoundation(label);if(v==='audit')loadAudit();if(v==='projectData')loadProjectDataManager();if(v==='control')loadControls();if(v==='controlAdvanced')loadAdvancedControl();if(v==='reportsAdvanced')loadDeliverables();if(v==='operations')loadOperations();if(v==='dataInspector')window.dataInspectorEnter?.();if(v==='supportCenter')window.supportEnter?.();if(v==='rodQc')window.topoEnter?.()}
function switchModule(name){if(name==='FieldBookSync'){location.href='/fieldbook';return}activeModule=modules[name]?name:'Home';$$('.module-tab').forEach(x=>x.classList.toggle('active',x.dataset.module===activeModule));const first=modules[activeModule].nav[0];switchView(first[2],first[1]);history.replaceState(null,'',activeModule==='Home'?'/' : `/?module=${encodeURIComponent(activeModule)}`)}
$$('.module-tab').forEach(b=>b.onclick=()=>switchModule(b.dataset.module));$$('[data-jump-module]').forEach(b=>b.onclick=()=>switchModule(b.dataset.jumpModule));$('#brandHome').onclick=()=>switchModule('Home');

function renderStatus(){const s=statusData,c=s.project,brand=s.branding||{};$('#brandBadge').textContent=brand.name||'SurveySync';$('#environmentBadge').textContent=(s.environment||'beta').toUpperCase();$('#envBar').style.background=s.environment==='production'?'#15815d':s.environment==='developer'?'#c94652':'#d29b2f';$('#projectPill').textContent=c?c.name:'No project open';$('#menubarProject').textContent=c?c.name:'No project open';$('#projectCrs').textContent=c?`${c.crs||'CRS not set'} · ${String(c.horizontal_units||'').replaceAll('_',' ')}`:'Choose New Project or Open Project.';const counts=c?.counts||{};$('#metrics').innerHTML=['sources','points','control_observations','open_qa','audit_events'].map(k=>`<div class="metric"><b>${counts[k]??0}</b><small>${k.replaceAll('_',' ')}</small></div>`).join('');$('#projectSummary').innerHTML=c?`<b>${esc(c.name)}</b><br>${esc(c.root)}<br><span class="muted">${esc(c.crs||'CRS not set')} · ${esc(c.horizontal_units)} / ${esc(c.vertical_units)}</span>`:'Create or open a SurveySync project.';renderProject(c)}
function coordinateSummary(settings){const c=settings||{},site=c.local_site||{};if(!c.crs)return 'Coordinate system not set.';const units=String(c.horizontal_units||'').replaceAll('_',' '),local=site.enabled?` · Local Site: ${esc(site.name||'Modified Ground')} · grid→ground ${Number(site.grid_to_ground_factor||1).toFixed(8)} · rotation ${Number(site.rotation_deg||0).toFixed(6)}°`:' · Grid coordinates';return `<b>${esc(c.name||c.crs)}</b><br><span class="muted">${esc(c.crs)} · ${esc(units)}${local}</span>`}
function renderProject(c){if(!c){$('#projectDetails').innerHTML='<span class="muted">No project open.</span>';if($('#projectCoordSummary'))$('#projectCoordSummary').textContent='Open a project first.';return}const db=c.database||{},tpl=c.project_template||{},coord=c.coordinate_system||{crs:c.crs,horizontal_units:c.horizontal_units,vertical_units:c.vertical_units,local_site:{enabled:false}};$('#projectDetails').innerHTML=`<b>${esc(c.name)}</b><p class="muted">Project ID: ${esc(c.project_id)}<br>${c.project_number?`Job: ${esc(c.project_number)}<br>`:''}${c.client?`Client: ${esc(c.client)}<br>`:''}Template: ${esc(tpl.name||tpl.id||'Standard Survey')}<br>Revision ${c.revision} · DB schema ${esc(db.schema_version??c.database_schema_version??'—')}<br>${esc(c.root)}<br>Created ${esc(c.created_utc)}</p>`;if($('#projectCoordSummary'))$('#projectCoordSummary').innerHTML=coordinateSummary(coord);if($('#coordStatusBadge'))$('#coordStatusBadge').textContent=coord.crs?(coord.local_site?.enabled?'LOCAL SITE':'GRID'):'NOT SET';if($('#migrationMsg'))$('#migrationMsg').textContent=`Migration: ${c.fieldbook_migration?.status||'NOT_MIGRATED'}`}
async function refresh(){statusData=await api('/api/v9/status');configData=await api('/api/v9/config');renderStatus();renderConfig()}
function renderConfig(){const c=configData;$('#environment').value=c.environment;$('#channel').value=c.release_channel;$('#branding').innerHTML=c.brands.map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('');$('#branding').value=c.branding_profile;$('#updateManifest').value=c.update_manifest_url||'';$('#feedbackEndpoint').value=c.feedback_endpoint||'';if($('#mainAiProvider'))$('#mainAiProvider').value=c.ai_provider||'auto';if(c.ui_appearance||c.ui_theme||c.ui_accent){const p={appearance:c.ui_appearance||'system',theme:c.ui_theme||'classic',accent:c.ui_accent||'default'};rememberSharedUiPrefs(p);applyAppearance(p.appearance,false);applyProductTheme(p.theme,false);applyAccent(p.accent,false)}updateAppearanceControls();refreshMainAi(false)}
function pathDirectory(value){const v=String(value||'').trim();if(!v)return '';const i=Math.max(v.lastIndexOf('\\'),v.lastIndexOf('/'));return i>0?v.slice(0,i):v}
async function chooseFolder(initial=''){if(window.pywebview?.api?.choose_folder){try{return await pywebview.api.choose_folder(initial||'')}catch(e){console.warn('Native folder picker failed; using local fallback',e)}}try{const d=await api('/api/v9/dialog/select-folder?initial_directory='+encodeURIComponent(initial||''));return d.path||''}catch(e){console.warn('Folder picker fallback failed',e);return ''}}
async function chooseFile(fileTypes=null,initial=''){if(window.pywebview?.api?.choose_file){try{return await pywebview.api.choose_file(initial||'',fileTypes||['All files (*.*)'])}catch(e){console.warn('Native file picker failed; using local fallback',e)}}try{const d=await api('/api/v9/dialog/select-file?initial_directory='+encodeURIComponent(initial||''));return d.path||''}catch(e){console.warn('File picker fallback failed',e);return ''}}
async function chooseFiles(fileTypes=null,initial=''){if(window.pywebview?.api?.choose_files){try{return await pywebview.api.choose_files(initial||'',fileTypes||['All files (*.*)'])}catch(e){console.warn('Native multi-file picker failed; using local fallback',e)}}try{const d=await api('/api/v9/dialog/select-files?initial_directory='+encodeURIComponent(initial||''));return d.paths||[]}catch(e){console.warn('Multi-file picker fallback failed',e);return []}}
function installPathBrowsers(){
  $$('[data-browse]').forEach(el=>{
    if(el.dataset.browseBound==='1')return;el.dataset.browseBound='1';
    const kind=el.dataset.browse;const wrap=document.createElement('div');wrap.className='path-picker-row';el.parentNode.insertBefore(wrap,el);wrap.appendChild(el);
    const b=document.createElement('button');b.type='button';b.className='secondary path-browse-btn';b.textContent=kind==='folder'?'Browse Folder…':kind==='files'?'Browse Files…':'Browse…';wrap.appendChild(b);
    b.onclick=async()=>{
      const current=String(el.value||'').trim();
      if(kind==='folder'){const v=await chooseFolder(current);if(v)el.value=v;return}
      if(kind==='files'){const vals=await chooseFiles(null,pathDirectory(current.split(/\r?\n/).filter(Boolean)[0]||''));if(vals.length)el.value=vals.join('\n');return}
      const v=await chooseFile(null,pathDirectory(current));if(v)el.value=v;
    };
  });
}

async function showProjectDialog(mode){
  openModalShell(mode==='new'?'new-project':'open-project');
  if(mode==='new'){
    let templates=[];try{templates=(await api('/api/v9/project-templates')).templates||[]}catch(_){templates=[{id:'standard',name:'Standard Survey'}]}
    const opts=templates.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');
    $('#modalBody').innerHTML=`<h2>New SurveySync Project</h2><p class="muted">Every project gets its own database, folders, audit trail and schema version. After creation, SurveySync immediately opens Project Coordinate System / Local Site setup before survey data is loaded.</p><label>Project name<input id="mName" placeholder="Project Name"></label><div class="grid2 compact"><label>Project number<input id="mNumber" placeholder="260184"></label><label>Client<input id="mClient" placeholder="Client / agency"></label></div><label>Project template<select id="mTemplate">${opts}</select></label><label>Save in folder<div class="row"><input id="mFolder" placeholder="C:\Projects"><button id="mBrowse" class="secondary">Browse</button></div></label><button id="mCreate" class="primary">Create Project & Set Coordinates</button>`;
    $('#mBrowse').onclick=async()=>{$('#mFolder').value=await chooseFolder()};
    $('#mCreate').onclick=async()=>{try{await jpost('/api/v9/project/create',{parent_folder:$('#mFolder').value,name:$('#mName').value,project_number:$('#mNumber').value,client:$('#mClient').value,template_id:$('#mTemplate').value,crs:'',horizontal_units:'us_survey_feet',vertical_units:'us_survey_feet'});closeModalShell();toast('Project database created from template');await refresh();await showCoordinateSystemDialog()}catch(e){toast(e.message)}};
    return;
  }
  $('#modalBody').innerHTML=`<h2>Open SurveySync Project</h2><p class="muted">Choose the project folder containing survey_sync_project.json. Older project databases are backed up and migrated automatically when required.</p><div class="row"><input id="mFolder" placeholder="C:\Projects\My Survey"><button id="mBrowse" class="secondary">Browse</button></div><button id="mOpen" class="primary">Open Project</button>`;
  $('#mBrowse').onclick=async()=>{$('#mFolder').value=await chooseFolder()};
  $('#mOpen').onclick=async()=>{try{await jpost('/api/v9/project/open',{path:$('#mFolder').value});closeModalShell();toast('Project opened');await refresh()}catch(e){toast(e.message)}};
}

async function showCoordinateSystemDialog(){
  if(!statusData?.project){toast('Open or create a project first.');return}
  let current;try{current=await api('/api/v9/project/coordinate-system')}catch(e){toast(e.message);return}
  const site=current.local_site||{};
  openModalShell('coordinate-system',true);
  $('#modalBody').innerHTML=`<div class="eyebrow">PROJECT COORDINATES</div><h2>Coordinate System & Local Site</h2><p class="muted">Browse the installed EPSG/ESRI library in folders, similar to ArcGIS, or search by name/WKID. SurveySync stores the grid CRS and Local Site ground transform separately so both remain auditable.</p><div class="crs-browser-shell"><div class="card-title"><div><b>Coordinate System Library</b><div class="muted">Projected and Geographic systems are organized into folders.</div></div></div><div id="coordBreadcrumbs" class="crs-breadcrumbs"></div><div class="crs-browser-grid"><div><div class="eyebrow">FOLDERS</div><div id="coordFolders" class="crs-browser-list"></div></div><div><div class="eyebrow">COORDINATE SYSTEMS</div><div id="coordSystems" class="crs-browser-list"></div></div></div></div><label>Search coordinate-system library<div class="row"><input id="coordSearch" class="grow" placeholder="Missouri East, Texas South Central, WGS 84, EPSG:2278"><button id="coordSearchBtn" class="secondary">Search</button></div></label><div id="coordSearchResults" class="crs-search-results"><div class="muted">Search results appear here.</div></div><label>Selected CRS / authority<input id="coordCrs" value="${esc(current.crs||'')}" placeholder="EPSG:2278"></label><div id="coordInspect" class="muted">${esc(current.name||'')}</div><div class="grid2 compact"><label>Horizontal units<select id="coordHUnits"><option value="us_survey_feet">US Survey Feet</option><option value="international_feet">International Feet</option><option value="meters">Meters</option></select></label><label>Vertical units<select id="coordVUnits"><option value="us_survey_feet">US Survey Feet</option><option value="international_feet">International Feet</option><option value="meters">Meters</option></select></label></div><hr><label style="display:flex;align-items:center;gap:8px"><input id="localSiteEnabled" type="checkbox" ${site.enabled?'checked':''}> Apply Local Site / modified-ground settings</label><div id="localSiteFields"><label>Local Site name<input id="localSiteName" value="${esc(site.name||'Local Site')}"></label><div class="formgrid"><label>Grid origin Northing<input id="gridOriginN" type="number" step="any" value="${Number(site.grid_origin_northing||0)}"></label><label>Grid origin Easting<input id="gridOriginE" type="number" step="any" value="${Number(site.grid_origin_easting||0)}"></label><label>Local/Ground origin Northing<input id="localOriginN" type="number" step="any" value="${Number(site.local_origin_northing||0)}"></label><label>Local/Ground origin Easting<input id="localOriginE" type="number" step="any" value="${Number(site.local_origin_easting||0)}"></label><label>Grid → Ground factor<input id="gridGroundFactor" type="number" step="0.00000001" value="${Number(site.grid_to_ground_factor||1)}"></label><label>Rotation (clockwise °)<input id="localRotation" type="number" step="0.000001" value="${Number(site.rotation_deg||0)}"></label></div><div class="notice"><b>Factor direction is explicit:</b> grid distance × Grid→Ground factor = Local Site / ground distance. No factor or rotation is inferred from the data.</div></div><div class="row"><button id="coordSave" class="primary">Save Project Coordinates</button><button id="coordCancel" class="secondary">Cancel</button></div>`;
  $('#coordHUnits').value=current.horizontal_units||'us_survey_feet';$('#coordVUnits').value=current.vertical_units||'us_survey_feet';
  const toggle=()=>{$('#localSiteFields').style.display=$('#localSiteEnabled').checked?'block':'none'};$('#localSiteEnabled').onchange=toggle;toggle();
  async function chooseCrs(value){
    if(!value)return;$('#coordCrs').value=value;
    try{const d=await jpost('/api/v9/crs/inspect',{crs:value});$('#coordInspect').textContent=d.valid?`${d.name} · ${d.authority||value}`:d.message;if(d.valid&&d.axes?.length){const unit=String(d.axes[0].unit_name||'').toLowerCase();if(unit.includes('us survey'))$('#coordHUnits').value='us_survey_feet';else if(unit==='foot'||unit.includes('international foot'))$('#coordHUnits').value='international_feet';else if(unit.includes('metre')||unit.includes('meter'))$('#coordHUnits').value='meters'}}catch(e){$('#coordInspect').textContent=e.message}
  }
  async function loadCrsFolder(path=''){
    try{
      const d=await api('/api/v9/crs/browser?limit=800&path='+encodeURIComponent(path));
      $('#coordBreadcrumbs').innerHTML=(d.breadcrumbs||[]).map((x,i)=>`<button type="button" class="crs-crumb ${i===(d.breadcrumbs.length-1)?'active':''}" data-path="${esc(x.path)}">${esc(x.name)}</button>`).join('<span>›</span>');
      $('#coordFolders').innerHTML=(d.folders||[]).length?(d.folders||[]).map(x=>`<button type="button" class="crs-folder-btn" data-path="${esc(x.path)}"><span>📁 ${esc(x.name)}</span><small>${Number(x.count||0).toLocaleString()}</small></button>`).join(''):'<div class="muted crs-empty">No subfolders.</div>';
      $('#coordSystems').innerHTML=(d.systems||[]).length?(d.systems||[]).map(x=>`<button type="button" class="crs-system-btn" data-crs="${esc(x.id)}"><b>${esc(x.name)}</b><small>${esc(x.id)}${x.area?` · ${esc(x.area)}`:''}</small></button>`).join(''):'<div class="muted crs-empty">Open a folder to choose a coordinate system.</div>';
      $$('.crs-crumb').forEach(b=>b.onclick=()=>loadCrsFolder(b.dataset.path||''));$$('.crs-folder-btn').forEach(b=>b.onclick=()=>loadCrsFolder(b.dataset.path||''));$$('.crs-system-btn').forEach(b=>b.onclick=()=>chooseCrs(b.dataset.crs||''));
    }catch(e){toast(e.message)}
  }
  async function searchLibrary(){try{const q=$('#coordSearch').value.trim();if(!q){$('#coordSearchResults').innerHTML='<div class="muted">Type a name, area, EPSG, or ESRI WKID.</div>';return}const d=await api('/api/v9/crs/library?limit=150&query='+encodeURIComponent(q)),rows=d.results||[];$('#coordSearchResults').innerHTML=rows.length?rows.map(x=>`<button type="button" class="crs-system-btn crs-search-hit" data-crs="${esc(x.id)}"><b>${esc(x.name)}</b><small>${esc(x.id)}${x.area?` · ${esc(x.area)}`:''}</small></button>`).join(''):'<div class="muted">No matches.</div>';$$('.crs-search-hit').forEach(b=>b.onclick=()=>chooseCrs(b.dataset.crs||''))}catch(e){toast(e.message)}}
  $('#coordSearchBtn').onclick=searchLibrary;$('#coordSearch').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();searchLibrary()}};
  $('#coordCancel').onclick=closeModalShell;
  $('#coordSave').onclick=async()=>{try{const payload={crs:$('#coordCrs').value.trim(),horizontal_units:$('#coordHUnits').value,vertical_units:$('#coordVUnits').value,local_site:{enabled:$('#localSiteEnabled').checked,name:$('#localSiteName').value,grid_origin_northing:+$('#gridOriginN').value,grid_origin_easting:+$('#gridOriginE').value,local_origin_northing:+$('#localOriginN').value,local_origin_easting:+$('#localOriginE').value,grid_to_ground_factor:+$('#gridGroundFactor').value,rotation_deg:+$('#localRotation').value}};await jpost('/api/v9/project/coordinate-system',payload);closeModalShell();toast('Project coordinate system saved');await refresh();if(activeView==='control')await loadControls()}catch(e){toast(e.message)}};
  $('#coordSearch').value='';await loadCrsFolder('');
}

let projectManagerItems=[];
function projectMetaLine(p){const bits=[];if(p.crs)bits.push(p.crs);if(p.horizontal_units)bits.push(String(p.horizontal_units).replaceAll('_',' '));if(p.modified_utc)bits.push(`Updated ${p.modified_utc}`);return bits.join(' · ')}
async function showProjectManager(){
  openModalShell('project-manager',true);$('#modalBody').innerHTML='<h2>Projects</h2><p class="muted">Loading projects…</p>';
  try{
    const d=await api('/api/v9/projects/recent');projectManagerItems=Array.isArray(d.projects)?d.projects:[];
    const rows=projectManagerItems.length?projectManagerItems.map((p,i)=>`<div class="project-manager-row ${p.active?'active':''}"><div class="project-manager-main"><div class="project-manager-title"><b>${esc(p.name||'Unnamed Project')}</b>${p.active?'<span class="brand-badge">CURRENT</span>':(!p.exists||!p.valid?'<span class="project-status-missing">MISSING</span>':'')}</div><div class="project-manager-path">${esc(p.path)}</div><div class="muted">${esc(projectMetaLine(p)||(!p.exists?'Project folder no longer exists.':'SurveySync project'))}</div></div><div class="project-manager-actions">${p.active?'<button class="secondary" disabled>Open</button>':`<button class="primary" data-project-action="open" data-project-index="${i}" ${(!p.exists||!p.valid)?'disabled':''}>Open</button>`}${p.active?'':`<button class="secondary" data-project-action="forget" data-project-index="${i}">Remove</button>`}<button class="danger" data-project-action="delete" data-project-index="${i}" ${(!p.exists||!p.valid)?'disabled':''}>Delete</button></div></div>`).join(''):'<div class="notice">No recent SurveySync projects yet. Create a project or open an existing project folder.</div>';
    $('#modalBody').innerHTML=`<div class="project-manager"><div class="eyebrow">PROJECT WORKSPACE</div><h2>Switch or Manage Projects</h2><p class="muted">Open a recent project with one click. Remove only clears an item from this list. Delete permanently removes the entire SurveySync project folder after confirmation.</p><div class="project-manager-list">${rows}</div><div class="row project-manager-footer"><button id="pmOpenOther" class="secondary">Open Other…</button><button id="pmNew" class="primary">New Project</button></div></div>`;
    $('#pmOpenOther').onclick=()=>showProjectDialog('open');$('#pmNew').onclick=()=>showProjectDialog('new');
    $$('[data-project-action]').forEach(b=>b.onclick=()=>handleProjectAction(b.dataset.projectAction,Number(b.dataset.projectIndex)));
  }catch(e){$('#modalBody').innerHTML=`<h2>Projects</h2><div class="notice warn">${esc(e.message)}</div>`}
}
async function handleProjectAction(action,index){
  const p=projectManagerItems[index];if(!p)return;
  if(action==='open'){
    try{await jpost('/api/v9/project/open',{path:p.path});closeModalShell();toast(`Opened ${p.name}`);await refresh()}catch(e){toast(e.message)}
    return;
  }
  if(action==='forget'){
    try{await jpost('/api/v9/project/forget',{path:p.path});toast('Removed from recent projects');await showProjectManager()}catch(e){toast(e.message)}
    return;
  }
  if(action==='delete')showDeleteProjectConfirm(p);
}
function showDeleteProjectConfirm(p){
  $('#modalBody').innerHTML=`<div class="delete-project-confirm"><div class="eyebrow">PERMANENT DELETE</div><h2>Delete ${esc(p.name)}?</h2><div class="notice warn"><b>This deletes the entire SurveySync project folder from this computer.</b><br>Source evidence, reports, exports, module data, audit history, attachments and project settings inside this folder will be removed. This cannot be undone by SurveySync.</div><p class="muted">Project folder:<br><span class="path-text">${esc(p.path)}</span></p><label>Type <b>${esc(p.name)}</b> to confirm<input id="deleteProjectName" autocomplete="off" placeholder="${esc(p.name)}"></label><div class="row"><button id="deleteProjectBack" class="secondary">Back</button><button id="deleteProjectNow" class="danger">Delete Project Permanently</button></div></div>`;
  $('#deleteProjectBack').onclick=()=>showProjectManager();
  const input=$('#deleteProjectName'),button=$('#deleteProjectNow');button.disabled=true;input.oninput=()=>button.disabled=input.value!==p.name;input.focus();
  button.onclick=async()=>{button.disabled=true;button.textContent='Deleting…';try{await jpost('/api/v9/project/delete',{path:p.path,confirm_name:input.value});toast(`${p.name} deleted`);await refresh();await showProjectManager()}catch(e){button.disabled=false;button.textContent='Delete Project Permanently';toast(e.message)}};
}
