async function loadDatabaseHealth(){try{const h=await api('/api/v9/database/health');$('#dbHealthBadge').textContent=h.integrity_ok&&h.schema_current&&!h.foreign_key_issues.length?'HEALTHY':'REVIEW';$('#dbHealth').innerHTML=`<div class="checks"><div>${h.integrity_ok?'✓':'!'} Integrity ${h.integrity_ok?'passed':'requires review'}</div><div>${h.schema_current?'✓':'!'} Schema ${h.schema_version} / ${h.required_schema_version}</div><div>${h.foreign_key_issues.length?'!':'✓'} ${h.foreign_key_issues.length} foreign-key issue(s)</div><div>${h.stale_results?'!':'✓'} ${h.stale_results} stale calculated result set(s)</div><div>Database size ${esc(formatBytes(h.size_bytes))}</div><div>Journal mode ${esc(h.journal_mode)}</div></div>`;return h}catch(e){$('#dbHealthBadge').textContent='ERROR';$('#dbHealth').textContent=e.message;return null}}
async function loadProjectDataManager(){if(!statusData?.project){$('#dataTable').innerHTML='<p class="muted">Open a SurveySync project first.</p>';return}try{const d=await api('/api/v9/data-manager/overview');dataManagerOverview=d;$('#dbSchemaBadge').textContent=`SCHEMA ${d.schema_version}`;$('#dataManagerMetrics').innerHTML=`<div class="metric"><b>${d.datasets.length}</b><small>datasets</small></div><div class="metric"><b>${formatBytes(d.size_bytes)}</b><small>database</small></div><div class="metric"><b>${d.stale_results}</b><small>stale results</small></div>`;const sel=$('#dataDataset'),prior=sel.value;sel.innerHTML=d.datasets.map(x=>`<option value="${esc(x.id)}">${esc(x.label)} (${Number(x.count||0).toLocaleString()})</option>`).join('');if(prior&&d.datasets.some(x=>x.id===prior))sel.value=prior;await Promise.all([loadDatabaseHealth(),loadDataDataset()])}catch(e){$('#dataTable').textContent=e.message}}
async function loadDataDataset(){const dataset=$('#dataDataset')?.value;if(!dataset)return;try{const d=await api(`/api/v9/data-manager/rows?dataset=${encodeURIComponent(dataset)}&search=${encodeURIComponent($('#dataSearch')?.value||'')}&limit=200`);dataManagerCurrent=d;$('#dataTableTitle').textContent=`${d.label} · ${Number(d.total||0).toLocaleString()} record(s)`;$('#dataModeBadge').textContent=d.mode==='readonly'?'READ ONLY':d.mode==='controlled'?'CONTROLLED EDIT':'EDITABLE';const cols=(d.columns||[]).slice(0,9),pk=d.pk;$('#dataTable').innerHTML=d.rows.length?`<table><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}${d.mode==='readonly'?'':'<th></th>'}</tr></thead><tbody>${d.rows.map((r,i)=>`<tr>${cols.map(c=>`<td title="${esc(dataCell(r[c]))}">${esc(dataCell(r[c]))}</td>`).join('')}${d.mode==='readonly'?'':`<td><button class="link-btn data-edit-row" data-row="${i}">Edit</button></td>`}</tr>`).join('')}</tbody></table>`:'<p class="muted">No records in this dataset.</p>';$$('.data-edit-row').forEach(b=>b.onclick=()=>openDataEdit(Number(b.dataset.row)))}catch(e){$('#dataTable').textContent=e.message}}
function openDataEdit(index){const d=dataManagerCurrent,r=d?.rows?.[index];if(!d||!r)return;const editable=d.editable_fields||[],pk=d.pk;openModalShell('data-edit');$('#modalBody').innerHTML=`<div class="eyebrow">PROJECT DATA MANAGER</div><h2>Edit ${esc(d.label)}</h2><p class="muted">Record ${esc(r[pk])}${d.mode==='controlled'?' · controlled survey data':' '}</p>${editable.map(f=>`<label>${esc(f)}<input class="data-edit-input" data-field="${esc(f)}" value="${esc(r[f]??'')}"></label>`).join('')}${d.mode==='controlled'?'<label>Reason for change<textarea id="dataEditReason" rows="3" placeholder="Required: explain why this survey value is being changed"></textarea></label><div class="notice warn">A safety snapshot will be created and dependent calculations will be marked stale until they are recalculated.</div>':''}<div class="row"><button id="dataEditCancel" class="secondary">Cancel</button><button id="dataEditSave" class="primary">Save Audited Edit</button></div>`;$('#dataEditCancel').onclick=closeModalShell;$('#dataEditSave').onclick=async()=>{try{const changes={};$$('.data-edit-input').forEach(x=>{if(String(x.value)!==String(r[x.dataset.field]??''))changes[x.dataset.field]=x.value});if(!Object.keys(changes).length)throw new Error('No values changed.');await jpost('/api/v9/data-manager/edit',{dataset:d.dataset,record_id:String(r[pk]),changes,reason:$('#dataEditReason')?.value||''});closeModalShell();toast('Audited project data edit saved');await loadProjectDataManager();await refresh()}catch(e){toast(e.message)}}}
if($('#dataDataset'))$('#dataDataset').onchange=loadDataDataset;if($('#dataSearchBtn'))$('#dataSearchBtn').onclick=loadDataDataset;if($('#dataRefreshBtn'))$('#dataRefreshBtn').onclick=loadProjectDataManager;if($('#dbHealthRefresh'))$('#dbHealthRefresh').onclick=loadDatabaseHealth;if($('#dbMaintenance'))$('#dbMaintenance').onclick=async()=>{if(!confirm('Create a safety snapshot and run safe database maintenance?'))return;try{const d=await api('/api/v9/database/maintenance',{method:'POST'});toast(d.ok?'Database maintenance completed':'Database maintenance completed with review findings');await loadProjectDataManager()}catch(e){toast(e.message)}};
