function renderControlImportDiagnostic(diags){const el=$('#controlImportDiagnostics');if(!el)return;const d=(diags||[])[0];if(!d){el.innerHTML='<p class="muted">No control source diagnostics yet.</p>';return}const x=d.summary||{},available=Object.entries(x.metadata_available||{}).filter(([,v])=>v).map(([k,v])=>`${esc(k.toUpperCase())}: ${v}`).join(' · '),missing=(x.missing_metadata||[]).map(k=>esc(String(k).toUpperCase())).join(', ');el.innerHTML=`<div class="notice ${missing?'warn':'good'}"><b>${esc(x.label||d.source_kind||'Control source')}</b>${available?`<br><b>Available:</b> ${available}`:''}${missing?`<br><b>Missing / unverified:</b> ${missing}`:''}${(x.warnings||[]).length?`<br>${(x.warnings||[]).map(esc).join('<br>')}`:''}</div>`}
