function renderMisnumberReview(data){const el=$('#controlMisnumberReview'),flags=data?.flags||[],overrides=new Map((data?.overrides||[]).map(x=>[String(x.observation_id),x]));if($('#controlMisnumberBadge'))$('#controlMisnumberBadge').textContent=`${flags.filter(x=>!overrides.has(String(x.observation_id))).length} REVIEW`;if(!el)return;el.innerHTML=flags.length?flags.map((f,i)=>{const ov=overrides.get(String(f.observation_id||''));return `<div class="notice ${ov?'good':'warn'}"><b>${esc(f.point_id||'Observation')}</b> → suggested Control ${esc(f.suggested_control_id||'—')}${f.suggested_point_id?` / ${esc(f.suggested_point_id)}`:''}<br>${esc(f.message||'')}<br><small>H distance ${f.distance_to_group_center==null?'—':Number(f.distance_to_group_center).toFixed(3)}${f.vertical_distance_to_group_center==null?'':` · V ${Number(f.vertical_distance_to_group_center).toFixed(3)}`} ${ov?`· ${esc(ov.status)}`:''}</small>${!ov&&f.observation_id?`<div class="row"><button class="secondary mis-confirm" data-i="${i}">Confirm</button><button class="secondary mis-reassign" data-i="${i}">Reassign…</button><button class="secondary mis-reject" data-i="${i}">Reject</button></div>`:''}</div>`}).join(''):'<p class="muted">No probable control misnumbers in the latest QC run.</p>';$$('.mis-confirm').forEach(b=>b.onclick=()=>saveMisnumberReview(flags[+b.dataset.i],'CONFIRMED'));$$('.mis-reject').forEach(b=>b.onclick=()=>saveMisnumberReview(flags[+b.dataset.i],'REJECTED'));$$('.mis-reassign').forEach(b=>b.onclick=()=>{const f=flags[+b.dataset.i],cid=prompt('Assign this observation to Control ID:',f.suggested_control_id||'');if(!cid)return;const pid=prompt('Effective shot Point ID:',f.suggested_point_id||cid);saveMisnumberReview(f,'REASSIGNED',cid,pid)})}
