 $('#controlMappingImport').onclick=async()=>{try{const map=collectControlMapping();const checked=await jpost('/api/v9/control/import-preview',{file_path:path,mapping:map,preview_rows:12});if(!checked.ready){renderControlMappingDialog(checked,path);toast('Complete the required column mappings before import.');return}await importControlWithMapping(path,checked.mapping,$('#controlRememberMapping')?.checked!==false)}catch(e){toast(e.message)}};
