function revisionSelectOptions(rows,kind){return (rows||[]).map(x=>{const state=x.active?' · ACTIVE':'';const detail=kind==='control'?`${x.method} · ${x.pass?'PASS':'REVIEW'}`:`${x.method||'none'} · closure ${x.closure==null?'—':Number(x.closure).toFixed(4)}`;return `<option value="${esc(x.solution_id)}">Rev ${x.revision}${state} · ${esc(detail)}</option>`}).join('')}
