async function showWhy(kind,id){try{const map={qa:'qa',point_review:'point',background_task:'task',import_stage:'import_stage'};const d=await api(`/api/v9/explain?kind=${encodeURIComponent(map[kind]||kind)}&object_id=${encodeURIComponent(id)}`);openModalShell('why');$('#modalBody').innerHTML=`<div class="eyebrow">WHY?</div><h2>${esc(d.title||'Evidence')}</h2><div class="notice"><b>${esc(d.severity||d.status||'INFO')}</b><br>${esc(d.why||'')}</div><pre>${esc(JSON.stringify(d.evidence||{},null,2))}</pre><p class="muted">${esc(d.guidance||'')}</p>`}catch(e){toast(e.message)}}
