async function loadProjectMap(){try{const d=await api('/api/v9/project-map'),f=d.features||[];if(!f.length){$('#projectMapCanvas').innerHTML='<span class="muted">No mappable project points yet.</span>';return}const xy=f.map(x=>x.geometry?.coordinates).filter(x=>Array.isArray(x)&&x.length>=2).map(x=>[Number(x[0]),Number(x[1])]).filter(x=>Number.isFinite(x[0])&&Number.isFinite(x[1]));if(!xy.length){$('#projectMapCanvas').innerHTML='<span class="muted">No finite coordinates.</span>';return}const xs=xy.map(x=>x[0]),ys=xy.map(x=>x[1]),minx=Math.min(...xs),maxx=Math.max(...xs),miny=Math.min(...ys),maxy=Math.max(...ys),dx=Math.max(1,maxx-minx),dy=Math.max(1,maxy-miny);const pts=f.map(x=>{const c=x.geometry?.coordinates||[],px=20+(Number(c[0])-minx)/dx*560,py=380-(Number(c[1])-miny)/dy*340,k=x.properties?.kind||'point',r=k==='control'?6:k==='utility_structure'?5:3;return `<circle cx="${px.toFixed(1)}" cy="${py.toFixed(1)}" r="${r}" fill="currentColor" opacity="${k==='survey_point'?'.55':'.9'}"><title>${esc(k)} ${esc(x.properties?.id||'')}</title></circle>`}).join('');$('#projectMapCanvas').innerHTML=`<svg viewBox="0 0 600 400" role="img" aria-label="Project coordinate overview"><rect x="1" y="1" width="598" height="398" fill="none" stroke="currentColor" opacity=".18"/>${pts}</svg><div class="muted">${f.length} feature(s) · CRS ${esc(d.crs||'not set')}</div>`}catch(e){if($('#projectMapCanvas'))$('#projectMapCanvas').textContent=e.message}}
