function renderMainAi(d){if(!d)return;const p=d.automatic_plan||{};const wo=d.windows_ocr||{};const fl=d.foundry_local||{};const configured=configData?.ai_provider||d.configured_provider||'auto';const cloud={gemini:'Gemini',openai:'OpenAI',anthropic:'Anthropic Claude'}[configured];if($('#mainAiPlan'))$('#mainAiPlan').textContent=cloud?`${cloud} — explicit cloud backup`:p.label||'Local AI status unavailable';if($('#mainAiBadge')){$('#mainAiBadge').textContent=cloud?'Cloud opt-in':(configured==='manual'?'Manual':p.effective_provider&&p.effective_provider!=='manual'?'Local AI ready':'Manual fallback');}if($('#mainAiDetails'))$('#mainAiDetails').textContent=cloud?`${cloud} is selected explicitly. Automatic local fallback remains available; cloud keys are session-only in FieldBookSync.`:`${p.reason||''} Windows AI OCR: ${wo.ready?'ready':wo.needs_download?'download available':wo.state||'unavailable'} · Foundry Local: ${fl.ready?'ready':fl.needs_download?'model download available':fl.state||'unavailable'} · Automatic never uses paid/cloud fallback.`;if($('#enableMainWindowsOcr'))$('#enableMainWindowsOcr').disabled=!!wo.ready||(!wo.needs_download&&!wo.supported);if($('#enableMainFoundry'))$('#enableMainFoundry').disabled=!!fl.ready||!fl.installed;}
async function refreshMainAi(show=true){try{const d=await api(`/api/v9/ai/status?refresh=${show?'true':'false'}`);renderMainAi(d);if(show)toast(`Automatic: ${(d.automatic_plan||{}).label||'status refreshed'}`);return d}catch(e){if(show)toast(e.message)}}
async function enableMainWindowsAi(){if(!confirm('Windows may download an on-device OCR component. Continue?'))return;try{const d=await api('/api/v9/ai/windows/enable?feature=ocr',{method:'POST'});renderMainAi(d.status);toast('Windows AI OCR is ready')}catch(e){toast(e.message)}}
async function enableMainFoundry(){if(!confirm('Download Microsoft Foundry Local vision model qwen3.5-vision for on-device use? This can use several GB of disk space.'))return;try{const d=await api('/api/v9/ai/foundry/enable',{method:'POST'});renderMainAi(d.status);toast('Foundry Local vision is ready')}catch(e){toast(e.message)}}
if($('#saveAiProvider'))$('#saveAiProvider').onclick=async()=>{try{const d=await jpost('/api/v9/config/ai',{ai_provider:$('#mainAiProvider').value});configData.ai_provider=d.ai_provider;toast('AI preference saved');await refreshMainAi(true)}catch(e){toast(e.message)}};
if($('#refreshMainAi'))$('#refreshMainAi').onclick=()=>refreshMainAi(true);if($('#enableMainWindowsOcr'))$('#enableMainWindowsOcr').onclick=enableMainWindowsAi;if($('#enableMainFoundry'))$('#enableMainFoundry').onclick=enableMainFoundry;


