if($('#scaleSolve'))$('#scaleSolve').onclick=async()=>{try{const samples=$('#scaleSamples').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map((line,i)=>{const [label,f,w]=line.split(',');return {label:label||`Sample ${i+1}`,factor:+f,weight:w?+w:1}});const d=await jpost('/api/v9/geodesy/project-factor',{name:$('#scaleName').value,samples,max_distortion_ppm:+$('#scaleMaxPpm').value,target_crs:statusData?.project?.crs||''});const rr=(d.residuals||[]);const rows=rr.map(x=>`<tr><td>${esc(x.label||'')}</td><td>${Number(x.local_factor??x.factor??0).toFixed(8)}</td><td>${Number(x.residual_ppm||0).toFixed(2)}</td><td>${Number(x.distortion_in_per_mile||0).toFixed(3)} in/mi</td></tr>`).join('');const max=Math.max(1,...rr.map(x=>Math.abs(Number(x.residual_ppm||0))));const bars=rr.map((x,i)=>{const v=Number(x.residual_ppm||0),w=Math.abs(v)/max*210,x0=v<0?240-w:240;return `<g><text x="8" y="${28+i*34}" font-size="12" fill="currentColor">${esc(x.label||'')}</text><rect x="${x0}" y="${14+i*34}" width="${Math.max(1,w)}" height="18" rx="3" fill="currentColor" opacity=".65"/><text x="465" y="${28+i*34}" text-anchor="end" font-size="11" fill="currentColor">${v.toFixed(2)} ppm</text></g>`}).join('');const chart=`<svg viewBox="0 0 480 ${Math.max(60,rr.length*34+12)}" style="width:100%;max-height:260px"><line x1="240" y1="4" x2="240" y2="${rr.length*34+6}" stroke="currentColor" opacity=".35"/>${bars}</svg>`;$('#scaleResult').innerHTML=`<div class="notice ${d.pass?'good':'warn'}"><b>Project factor ${Number(d.project_factor).toFixed(9)}</b><br>Max residual ${Number(d.max_abs_ppm).toFixed(2)} ppm · RMS ${Number(d.rms_ppm).toFixed(2)} ppm · ${d.pass?'Within selected threshold':'Review required'}</div>${chart}<div class="table"><table><thead><tr><th>Sample</th><th>Factor</th><th>Residual ppm</th><th>Distortion</th></tr></thead><tbody>${rows}</tbody></table></div>`}catch(e){toast(e.message)}};
