$('#checkUpdate').onclick=async()=>{
  const b=$('#checkUpdate');b.disabled=true;b.textContent='Checking…';$('#updateResult').textContent='Checking the active SurveySync release channel…';
  try{
    const info=await api('/api/v9/update/check',{timeoutMs:30000});
    if(!info.update_available){
      $('#updateResult').textContent=`SurveySync v${info.current_version||''} is current on the ${info.channel||'selected'} channel.`;
      b.disabled=false;b.textContent='Check & Update';toast('SurveySync is up to date');
      return;
    }
    const ok=confirm(`SurveySync ${info.version} is available on the ${info.channel||'selected'} channel.\n\nInstall it now? SurveySync will close after the verified installer is staged, then Setup will open.`);
    if(!ok){
      $('#updateResult').textContent=`SurveySync v${info.version} is available. Install when you are ready for the app to close.`;
      b.disabled=false;b.textContent='Check & Update';
      return;
    }
    b.textContent='Downloading…';$('#updateResult').textContent='Downloading and verifying the installer…';
    const r=await api('/api/v9/update/check-and-install',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirm_install:true}),timeoutMs:0});
    $('#updateResult').textContent=r.message||JSON.stringify(r,null,2);
    if(r.action==='installing'){b.textContent='Update verified — closing…';toast(r.message||'Update verified. Setup will open automatically.')}
    else{b.disabled=false;b.textContent='Check & Update';toast(r.message||'SurveySync is up to date')}
  }catch(e){b.disabled=false;b.textContent='Check & Update';$('#updateResult').textContent=e.message;toast(e.message)}
};
